from __future__ import annotations

import re
from typing import Optional

# ---------------------------------------------------------------------------
# Hand-rolled helpers so this file needs no framework imports. The framework
# discovers tools by a `TOOLS` dict of name -> callable.
# ---------------------------------------------------------------------------


def _ticket(t):
    """Normalise a ticket object to a dict we can read and write."""
    if hasattr(t, "get"):
        return t
    return t


def _get(t, key, default=None):
    t = _ticket(t)
    if hasattr(t, "get"):
        return t.get(key, default)
    return default


def _set(t, **fields):
    t = _ticket(t)
    if hasattr(t, "set_fields"):
        t.set_fields(**fields)
    return {"ok": True, "fields": list(fields)}


# ---------------------------------------------------------------------------
# Rules
# ---------------------------------------------------------------------------


def get_money_policy(ticket):
    """One call answering every cost question: quoting is free, the deposit is 20%
    and the consultant takes it, insurance is quoted separately."""
    return {
        "quoting_fee": "Free — no fee, no card, nothing taken in the chat",
        "deposit": "A 20% deposit, taken by your consultant when you book — never here",
        "insurance": "Travel insurance is quoted separately, alongside the trip",
    }


def get_decline(ticket, key=None):
    """The three refusals, verbatim, by key. Returns all three if no key given."""
    lines = {
        "destination": (
            "We're not able to arrange travel to Cuba, I'm afraid — it's not somewhere "
            "we book. If there's anywhere else you're considering, I'd be glad to help."
        ),
        "visa": (
            "We don't handle visa applications, so that part you'd do yourself. Your "
            "consultant will tell you which visas you need when they come back with "
            "the options."
        ),
        "insurance_only": (
            "We only arrange travel insurance alongside a trip we've booked for you, "
            "so on its own it isn't something we can sell. If you're planning a trip, "
            "we'd be glad to quote both together."
        ),
    }
    if key and key in lines:
        return {"key": key, "line": lines[key]}
    return {"keys": list(lines), "lines": lines}


def check_destination(ticket, destination=None):
    """Decide, in code, whether we go there, which region it is, and whose enquiry it
    is. Remembers the region and the consultant to the ticket."""
    if destination is None:
        destination = _get(ticket, "destination", "")
    dest = (destination or "").strip().lower()

    refused = {
        "cuba": "Cuba",
        "iran": "Iran",
    }
    if dest in refused:
        return {"ok": False, "refused": True, "destination": refused[dest]}

    # Region -> consultant. Multi-region or unmatched -> rota.
    region = _consultant_for(destination)
    consultant = _get(ticket, "consultant", region.get("consultant", "the enquiry rota"))
    region_name = region.get("region", "Other")

    _set(ticket, region=region_name, consultant=consultant)
    return {
        "ok": True,
        "refused": False,
        "region": region_name,
        "consultant": consultant,
    }


def _consultant_for(destination):
    d = (destination or "").lower()
    asia = ["japan", "tokyo", "thailand", "bangkok", "vietnam", "china", "india",
            "korea", "seoul", "singapore", "malaysia", "bali", "indonesia", "philippines",
            "taiwan", "hong kong", "cambodia", "laos", "myanmar", "nepal", "sri lanka",
            "mongolia", "kazakhstan", "uzbekistan"]
    if any(k in d for k in asia):
        return {"region": "Asia", "consultant": "Sam"}

    europe = ["france", "paris", "italy", "rome", "lisbon", "portugal", "spain", "madrid",
              "germany", "berlin", "uk", "london", "england", "ireland", "dublin",
              "greece", "athens", "netherlands", "amsterdam", "switzerland", "zurich",
              "austria", "vienna", "belgium", "brussels", "croatia", "czech", "prague",
              "denmark", "sweden", "norway", "finland", "poland", "hungary", "budapest"]
    americas = ["usa", "united states", "new york", "california", "canada", "toronto",
                "mexico", "cancun", "brazil", "rio", "argentina", "buenos aires", "chile",
                "peru", "lima", "colombia", "bogota", "costa rica", "panama", "ecuador",
                "guatemala", "caribbean", "jamaica", "cuba", "dominican"]
    if any(k in d for k in europe):
        return {"region": "Europe", "consultant": "Priya"}
    if any(k in d for k in americas):
        return {"region": "Americas", "consultant": "Priya"}

    return {"region": "Other", "consultant": "the enquiry rota"}


# ---------------------------------------------------------------------------
# Client
# ---------------------------------------------------------------------------


def client_lookup(ticket, phone=None, email=None):
    """Look a client up by phone or email. Returns whether we have travelled them
    before and any details we hold. Takes either; takes either together."""
    contact = phone or email
    if not contact:
        return {"found": False, "reason": "no contact given"}
    # In this build there is no real record store; return not-found so the flow
    # treats every enquiry as a fresh sheet, exactly as the plan assumes.
    return {"found": False, "contact": contact, "known_customer": "no"}


def client_save(ticket, name=None, phone=None, email=None, language=None):
    """Record the client. There is no service address here, so this is lighter than
    the preset's crm.create_customer."""
    fields = {}
    if name:
        fields["name"] = name
    if phone:
        fields["phone"] = phone
    if email:
        fields["email"] = email
    if language:
        fields["language"] = language
    _set(ticket, **fields)
    return {"ok": True, "saved": list(fields)}


# ---------------------------------------------------------------------------
# Consultant
# ---------------------------------------------------------------------------


def consultant_send_enquiry(ticket):
    """The heart of the project. Reads the ticket and refuses to send an enquiry
    missing any of the five must-haves. Names the consultant itself from the ticket.
    Returns the deposit and insurance sentences alongside the confirmation."""
    missing = []
    for field in ["party", "route", "budget", "passports", "scope"]:
        if not _get(ticket, field):
            missing.append(field)

    if missing:
        return {
            "ok": False,
            "sent": False,
            "missing": missing,
            "message": (
                "Cannot send this enquiry yet — it is missing: "
                + ", ".join(missing)
                + ". Call ticket.set_fields first."
            ),
        }

    consultant = _get(ticket, "consultant", "the enquiry rota")
    name = _get(ticket, "name", "the client")
    result = {
        "ok": True,
        "sent": True,
        "to": consultant,
        "confirmation": (
            f"Your enquiry for {name} is on its way to {consultant}, who will come back "
            "with options and a price."
        ),
        "deposit_sentence": (
            "When you book, the deposit is 20% and your consultant takes it — never "
            "anything in this chat."
        ),
        "insurance_sentence": (
            "And travel insurance is always quoted separately, alongside the trip."
        ),
    }
    _set(ticket, sent_to=consultant)
    return result


# ---------------------------------------------------------------------------
# Tool registry
# ---------------------------------------------------------------------------

TOOLS = {
    "consultant.send_enquiry": consultant_send_enquiry,
    "rules.check_destination": check_destination,
    "rules.get_decline": get_decline,
    "rules.get_money_policy": get_money_policy,
    "client.lookup": client_lookup,
    "client.save": client_save,
}"}

